//! The README banner is generated by `examples/banner.rs` and must match the committed file.
//! After a layout change: `MATHRA_UPDATE_BANNER=1 cargo test -p mathra --test banner`.

#[path = "../examples/banner.rs"]
mod banner;

#[test]
fn banner_is_deterministic_and_up_to_date() {
    let generated = banner::generate();
    assert_eq!(generated, banner::generate(), "same version, same bytes");
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/banner.svg");
    if std::env::var_os("MATHRA_UPDATE_BANNER").is_some() {
        std::fs::write(path, &generated).unwrap();
    }
    let committed = std::fs::read_to_string(path).expect("docs/banner.svg exists");
    assert!(committed == generated, "docs/banner.svg is stale: run with MATHRA_UPDATE_BANNER=1");
}
